create index if not exists chats_user_created_idx on public.chats(user_id, created_at desc); create index if not exists messages_user_created_idx on public.messages(user_id, created_at desc); create index if not exists messages_chat_created_idx on public.messages((data->>'chat_id'), created_at desc); create index if not exists chats_funnel_idx on public.chats((data->>'funnel_id'), created_at desc); create index if not exists chats_session_idx on public.chats((data->>'session_id'), created_at desc); create index if not exists chats_lead_idx on public.chats((data->>'lead_id'), created_at desc); create index if not exists messages_external_idx on public.messages(user_id, ((data->>'external_id'))) where data ? 'external_id';